<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Interview Experience Moderation</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#102445;font-family:Inter,system-ui,sans-serif}.wrap{width:min(1200px,calc(100% - 32px));margin:40px auto}.tabs{display:flex;gap:8px;margin:18px 0}.tabs a,.btn{padding:10px 14px;border-radius:8px;background:#e5efff;color:#1557b4;text-decoration:none;border:0;font-weight:800}.tabs .active,.btn.approve{background:#1768e8;color:#fff}.btn.reject{background:#b91c1c;color:#fff}.card{background:#fff;border:1px solid #d7e1ef;border-radius:14px;padding:21px;margin:14px 0}.meta{color:#657994}.round{padding:12px;background:#f6f9fd;border-radius:9px;margin:8px 0}.actions{display:flex;gap:9px;margin-top:15px}.pagination{display:flex;gap:6px;list-style:none}.page-link{padding:8px;border:1px solid #ccd9e8;border-radius:7px;text-decoration:none}</style></head><body><main class="wrap"><a href="{{route('admin.dashboard')}}">← Owner dashboard</a><h1>Company experience moderation</h1><div class="tabs">@foreach(['pending','approved','rejected','all'] as $tab)<a class="{{$status===$tab?'active':''}}" href="{{route('admin.company-experiences.index',['status'=>$tab])}}">{{ucfirst($tab)}}</a>@endforeach</div>@forelse($items as $item)<article class="card"><div class="meta">{{$item->company->name}} · {{$item->role?->role_name}} · {{$item->location}} · submitted by {{$item->user?->email??'Unknown'}}</div><h2>{{ucfirst($item->result)}} · {{ucwords(str_replace('_',' ',$item->difficulty))}}</h2><p>{!!nl2br(e($item->overall_experience))!!}</p>@foreach($item->rounds as $round)<div class="round"><b>Round {{$round->round_number}}: {{$round->round_name}}</b><br>{{$round->description}}</div>@endforeach @if($item->moderation_status==='pending')<div class="actions"><form method="post" action="{{route('admin.company-experiences.moderate',$item)}}">@csrf @method('patch